import React, { useEffect, useRef, useState } from "react";
import { Camera, Eye, EyeOff, LockKeyhole, Save, UserCircle } from "lucide-react";
import AppShell from "./AppShell";
import OtpModal from "./OtpModal";
import { confirmPasswordChange, confirmProfileEmailChange, getProfile, requestPasswordChange, requestProfileUpdate, updateProfile, uploadProfileAvatar } from "../services/profileService";
import PasswordChecklist from "./PasswordChecklist";
import {
  isValidPhMobile, INVALID_PH_MOBILE_MESSAGE, validateImageFile, validatePassword, validatePasswordsMatch,
  FIRST_NAME_REQUIRED_MESSAGE, LAST_NAME_REQUIRED_MESSAGE, sanitizePhoneInput,
} from "../utils/validators";
import { focusFirstInvalidField, invalidClass } from "../utils/formValidation";

function validateProfileField(name, value, isOwner) {
  switch (name) {
    case "firstName":
      return String(value || "").trim() ? "" : FIRST_NAME_REQUIRED_MESSAGE;
    case "lastName":
      return String(value || "").trim() ? "" : LAST_NAME_REQUIRED_MESSAGE;
    case "username":
      return String(value || "").trim() ? "" : "Username is required.";
    case "email": {
      const trimmed = String(value || "").trim();
      if (!trimmed) return "Email is required.";
      if (!/^\S+@\S+\.\S+$/.test(trimmed)) return "Please enter a valid email address.";
      return "";
    }
    case "phone": {
      const trimmed = String(value || "").trim();
      if (!trimmed) return isOwner ? "Contact number is required." : "";
      return isValidPhMobile(trimmed) ? "" : INVALID_PH_MOBILE_MESSAGE;
    }
    default:
      return "";
  }
}

function validatePasswordField(name, passwords) {
  switch (name) {
    case "current":
      return String(passwords.current || "") ? "" : "Current password is required.";
    case "next": {
      if (!String(passwords.next || "")) return "New password is required.";
      try { validatePassword(passwords.next); return ""; } catch (error) { return error.message; }
    }
    case "confirm": {
      if (!String(passwords.confirm || "")) return "Please confirm your new password.";
      try { validatePasswordsMatch(passwords.next, passwords.confirm); return ""; } catch (error) { return error.message; }
    }
    default:
      return "";
  }
}

function splitFullName(fullName) {
  const parts = String(fullName || "").trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return { firstName: "", middleName: "", lastName: "" };
  if (parts.length === 1) return { firstName: parts[0], middleName: "", lastName: "" };
  if (parts.length === 2) return { firstName: parts[0], middleName: "", lastName: parts[1] };
  return { firstName: parts[0], middleName: parts.slice(1, -1).join(" "), lastName: parts[parts.length - 1] };
}

function joinFullName({ firstName, middleName, lastName }) {
  return [firstName, middleName, lastName].map((part) => String(part || "").trim()).filter(Boolean).join(" ");
}

export default function UserProfileModule({ profile, title = "My Profile" }) {
  const [form, setForm] = useState({ firstName: "", middleName: "", lastName: "", username: "", email: "", phone: "", address: "", avatar_url: "" });
  const [passwords, setPasswords] = useState({ current: "", next: "", confirm: "" });
  const [show, setShow] = useState({ current: false, next: false, confirm: false });
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [message, setMessage] = useState({ type: "", text: "" });
  const [otpModal, setOtpModal] = useState({ open: false, email: "", purpose: "", title: "" });
  const [fieldErrors, setFieldErrors] = useState({});
  const [passwordFieldErrors, setPasswordFieldErrors] = useState({});
  const passwordSectionRef = useRef(null);
  const detailFieldRefs = useRef({}).current;
  const passwordFieldRefs = useRef({}).current;
  const registerDetailFieldRef = (name) => (el) => { detailFieldRefs[name] = el; };
  const registerPasswordFieldRef = (name) => (el) => { passwordFieldRefs[name] = el; };
  const forcePasswordChange = !!profile?.must_change_password;
  const isOwner = profile?.role === "pet_owner";

  useEffect(() => {
    if (forcePasswordChange) passwordSectionRef.current?.scrollIntoView({ behavior: "smooth", block: "start" });
  }, [forcePasswordChange]);

  useEffect(() => {
    let active = true;
    async function load() {
      try {
        const data = await getProfile(profile.id);
        if (active) setForm({
          ...splitFullName(data.full_name), username: data.username || "", email: data.email || "",
          phone: data.phone || "", address: data.address || "", avatar_url: data.avatar_url || ""
        });
      } catch (error) {
        if (active) setMessage({ type: "error", text: error.message });
      } finally { if (active) setLoading(false); }
    }
    if (profile?.id) load();
    return () => { active = false; };
  }, [profile?.id]);

  function field(name, value) {
    setForm((current) => ({ ...current, [name]: value }));
    if (fieldErrors[name]) {
      setFieldErrors((current) => ({ ...current, [name]: validateProfileField(name, value, isOwner) }));
    }
  }

  async function saveDetails(event) {
    event.preventDefault(); setMessage({ type: "", text: "" });

    const errors = {};
    ["firstName", "lastName", "username", "email", "phone"].forEach((name) => {
      const errorMessage = validateProfileField(name, form[name], isOwner);
      if (errorMessage) errors[name] = errorMessage;
    });

    setFieldErrors(errors);

    if (Object.keys(errors).length > 0) {
      setMessage({ type: "error", text: "Please fix the highlighted field(s) before continuing." });
      focusFirstInvalidField(detailFieldRefs, errors);
      return;
    }

    setSaving(true);
    try {
      const result = await requestProfileUpdate(profile.id, { ...form, full_name: joinFullName(form) }, profile.role);
      if (result.requiresOtp) {
        setOtpModal({ open: true, email: result.email, purpose: "change_email", title: "Verify Email Change" });
        setMessage({ type: "success", text: "OTP sent to your new email address." });
      } else {
        setForm((current) => ({ ...current, ...result.updated, ...splitFullName(result.updated.full_name) }));
        setMessage({ type: "success", text: "Profile updated successfully." });
      }
    } catch (error) { setMessage({ type: "error", text: error.message }); }
    finally { setSaving(false); }
  }

  async function chooseAvatar(event) {
    const file = event.target.files?.[0]; if (!file) return;
    setMessage({ type: "", text: "" });
    try {
      validateImageFile(file);
    } catch (error) {
      event.target.value = "";
      return setMessage({ type: "error", text: error.message });
    }
    setUploading(true);
    try {
      const avatar_url = await uploadProfileAvatar(profile.id, file);
      const updated = await updateProfile(profile.id, { ...form, full_name: joinFullName(form), avatar_url }, profile.role);
      setForm((current) => ({ ...current, avatar_url: updated.avatar_url }));
      setMessage({ type: "success", text: "Profile photo updated." });
    } catch (error) { setMessage({ type: "error", text: error.message }); }
    finally { setUploading(false); event.target.value = ""; }
  }

  async function savePassword(event) {
    event.preventDefault(); setMessage({ type: "", text: "" });

    const errors = {};
    ["current", "next", "confirm"].forEach((name) => {
      const errorMessage = validatePasswordField(name, passwords);
      if (errorMessage) errors[name] = errorMessage;
    });

    setPasswordFieldErrors(errors);

    if (Object.keys(errors).length > 0) {
      setMessage({ type: "error", text: "Please fix the highlighted field(s) before continuing." });
      focusFirstInvalidField(passwordFieldRefs, errors);
      return;
    }

    setSaving(true);
    try {
      const result = await requestPasswordChange(profile.id, passwords.current, passwords.next);
      setOtpModal({ open: true, email: result.email, purpose: "change_password", title: "Verify Password Change" });
      setMessage({ type: "success", text: "OTP sent to your registered email." });
    } catch (error) { setMessage({ type: "error", text: error.message }); }
    finally { setSaving(false); }
  }


  async function verifyProfileOtp(code) {
    if (otpModal.purpose === "change_email") {
      const updated = await confirmProfileEmailChange(code);
      setForm((current) => ({ ...current, ...updated, ...splitFullName(updated.full_name) }));
      setMessage({ type: "success", text: "Email and profile updated successfully." });
    } else if (otpModal.purpose === "change_password") {
      await confirmPasswordChange(code);
      setPasswords({ current: "", next: "", confirm: "" });
      setPasswordFieldErrors({});
      setMessage({ type: "success", text: "Password changed successfully." });
    }
    setOtpModal({ open: false, email: "", purpose: "", title: "" });
  }

  function passwordField(name, value) {
    setPasswords((current) => {
      const next = { ...current, [name]: value };
      if (passwordFieldErrors[name] || (name === "next" && passwordFieldErrors.confirm)) {
        setPasswordFieldErrors((currentErrors) => {
          const nextErrors = { ...currentErrors, [name]: validatePasswordField(name, next) };
          if (name === "next" && currentErrors.confirm) {
            nextErrors.confirm = validatePasswordField("confirm", next);
          }
          return nextErrors;
        });
      }
      return next;
    });
  }

  const PasswordField = ({ name, label }) => (
    <label>
      <span>{label}<span className="required-mark"> *</span></span>
      <div className={`passwordBox${passwordFieldErrors[name] ? " field-invalid" : ""}`}>
        <input
          ref={registerPasswordFieldRef(name)}
          type={show[name] ? "text" : "password"}
          value={passwords[name]}
          onChange={(e) => passwordField(name, e.target.value)}
          required
        />
        <button type="button" onClick={()=>setShow((s)=>({...s,[name]:!s[name]}))}>{show[name]?<EyeOff size={18}/>:<Eye size={18}/>}</button>
      </div>
      {passwordFieldErrors[name] && <span className="field-error-text">{passwordFieldErrors[name]}</span>}
    </label>
  );

  return <AppShell profile={profile} title={title}><div className="profilePage">
    {forcePasswordChange && <div className="warn">You're using a temporary password. Please set a new password below to continue.</div>}
    {message.text && <div className={message.type}>{message.text}</div>}
    <section className="profileHero card">
      <div className="avatarWrap">
        <div className="avatarImg">{form.avatar_url ? <img src={form.avatar_url} alt="Profile"/> : <UserCircle size={56}/>}</div>
        <label className="camera"><Camera size={14}/><input type="file" accept="image/jpeg,image/jpg,image/png,image/webp" onChange={chooseAvatar}/></label>
      </div>
      <div className="profileHeroInfo"><h2>{joinFullName(form) || profile.full_name}</h2><p>@{form.username || profile.username}</p><span>{String(profile.role || "").replaceAll("_", " ")}</span>{uploading && <small> Uploading photo...</small>}</div>
    </section>
    {loading ? <div className="card">Loading profile...</div> : <div className="columns">
      <form className="card form" onSubmit={saveDetails} noValidate><h3><UserCircle size={20}/> Personal Information</h3>
        <div className="pair">
          <label><span>First name<span className="required-mark"> *</span></span><input ref={registerDetailFieldRef("firstName")} className={invalidClass(fieldErrors, "firstName")} value={form.firstName} onChange={(e)=>field("firstName",e.target.value)} required/>{fieldErrors.firstName && <span className="field-error-text">{fieldErrors.firstName}</span>}</label>
          <label><span>Last name<span className="required-mark"> *</span></span><input ref={registerDetailFieldRef("lastName")} className={invalidClass(fieldErrors, "lastName")} value={form.lastName} onChange={(e)=>field("lastName",e.target.value)} required/>{fieldErrors.lastName && <span className="field-error-text">{fieldErrors.lastName}</span>}</label>
        </div>
        <label><span>Middle name<span className="optional-mark"> (Optional)</span></span><input value={form.middleName} onChange={(e)=>field("middleName",e.target.value)}/></label>
        <div className="pair">
          <label><span>Username<span className="required-mark"> *</span></span><input ref={registerDetailFieldRef("username")} className={invalidClass(fieldErrors, "username")} value={form.username} onChange={(e)=>field("username",e.target.value)} required/>{fieldErrors.username && <span className="field-error-text">{fieldErrors.username}</span>}</label>
          <label><span>Email<span className="required-mark"> *</span></span><input ref={registerDetailFieldRef("email")} className={invalidClass(fieldErrors, "email")} type="email" value={form.email} onChange={(e)=>field("email",e.target.value)} required/>{fieldErrors.email && <span className="field-error-text">{fieldErrors.email}</span>}</label>
        </div>
        {isOwner
          ? <label><span>Contact number<span className="required-mark"> *</span></span><input ref={registerDetailFieldRef("phone")} className={invalidClass(fieldErrors, "phone")} type="tel" inputMode="numeric" maxLength={11} value={form.phone} onChange={(e)=>field("phone",sanitizePhoneInput(e.target.value))} placeholder="09XXXXXXXXX" required/>{fieldErrors.phone && <span className="field-error-text">{fieldErrors.phone}</span>}</label>
          : <label><span>Phone number<span className="optional-mark"> (Optional)</span></span><input ref={registerDetailFieldRef("phone")} className={invalidClass(fieldErrors, "phone")} type="tel" inputMode="numeric" maxLength={11} value={form.phone} onChange={(e)=>field("phone",sanitizePhoneInput(e.target.value))} placeholder="09XXXXXXXXX"/>{fieldErrors.phone && <span className="field-error-text">{fieldErrors.phone}</span>}</label>}
        <label><span>Address<span className="optional-mark"> (Optional)</span></span><textarea value={form.address} onChange={(e)=>field("address",e.target.value)}/></label>
        <button disabled={saving}><Save size={17}/>{saving?"Saving...":"Save Profile"}</button>
      </form>
      <form className={`card form${forcePasswordChange ? " highlight" : ""}`} onSubmit={savePassword} ref={passwordSectionRef} noValidate><h3><LockKeyhole size={20}/> Change Password</h3>
        <PasswordField name="current" label="Current password"/>
        <PasswordField name="next" label="New password"/>
        <PasswordChecklist password={passwords.next}/>
        <PasswordField name="confirm" label="Confirm new password"/>
        <button disabled={saving}><LockKeyhole size={17}/>{saving?"Saving...":"Change Password"}</button>
        <p className="note">Each password field has its own show/hide button.</p>
      </form>
    </div>}
    <style>{`.profilePage{display:grid;gap:14px}.profileHero{display:flex;align-items:center;gap:14px;flex-wrap:wrap}.avatarWrap{position:relative;width:88px;height:88px;flex-shrink:0}.avatarImg{width:100%;height:100%;border-radius:50%;overflow:hidden;background:#e6f6fc;color:#4DA8DA;display:grid;place-items:center}.avatarImg img{width:100%;height:100%;object-fit:cover;display:block}.camera{position:absolute;right:-2px;bottom:-2px;background:#4DA8DA;color:#fff;width:28px;height:28px;border-radius:50%;display:grid!important;place-items:center;cursor:pointer;border:2px solid #fff;box-shadow:0 2px 6px rgba(20,73,94,.18)}.camera input{display:none}.profileHeroInfo{min-width:0}.profileHeroInfo h2{margin:0 0 4px;overflow-wrap:anywhere}.profileHeroInfo p{margin:0 0 8px;color:#6F7F88}.profileHeroInfo span{background:#e7f6fc;color:#267fa9;padding:6px 10px;border-radius:999px;text-transform:capitalize;font-size:12px}.columns{display:grid;grid-template-columns:1.25fr .85fr;gap:14px}.form{display:grid;gap:13px}.form h3{display:flex;align-items:center;gap:8px;margin:0 0 6px}.form label{display:grid;gap:6px;font-size:13px;font-weight:700}.form input,.form textarea{width:100%;border:1px solid #d8e8ef;border-radius:10px;padding:11px;font:inherit}.form textarea{min-height:100px;resize:vertical}.pair{display:grid;grid-template-columns:1fr 1fr;gap:12px}.form>button{justify-self:start;border:0;border-radius:10px;padding:11px 15px;background:#4DA8DA;color:#fff;display:flex;align-items:center;gap:7px;cursor:pointer}.passwordBox{display:flex;border:1px solid #d8e8ef;border-radius:10px;overflow:hidden}.passwordBox input{border:0}.passwordBox button{border:0;background:#fff;color:#54707d;padding:0 12px;cursor:pointer}.note{font-size:12px;color:#6F7F88}.error,.success,.warn{padding:12px 14px;border-radius:11px}.error{background:#fff0f0;color:#a94444}.success{background:#eaf8ef;color:#28794c}.warn{background:#fff5d9;color:#9a7015;font-weight:700}.form.highlight{outline:2px solid #f0c869;outline-offset:2px}@media(max-width:850px){.columns{grid-template-columns:1fr}.pair{grid-template-columns:1fr}.profileHero{flex-direction:column;text-align:center;gap:12px}}`}</style>
    <OtpModal open={otpModal.open} email={otpModal.email} purpose={otpModal.purpose} title={otpModal.title} onVerify={verifyProfileOtp} onClose={()=>setOtpModal({ open:false,email:"",purpose:"",title:"" })}/>
  </div></AppShell>;
}
